async def act(page):
    # No knowledge_base helper functions are available (the <functions> list is empty),
    # so use Playwright APIs directly.

    # We'll update both the shipping and billing addresses for the order.
    # From the current page there are two Edit links with URLs:
    # - /index.php/admin/sales_order/address/address_id/868/  (billing)
    # - /index.php/admin/sales_order/address/address_id/869/  (shipping)
    # We'll navigate to the shipping address edit page first, update fields,
    # Save, then navigate to the billing edit page and do the same.

    async def fill_address_fields():
        # Fill Street
        street_labels = ["Street Address", "Street 1", "Street", "Address", "Address 1"]
        for lbl in street_labels:
            try:
                await page.get_by_label(lbl).fill("789 Pine Lane")
                break
            except Exception:
                continue

        # Fill City
        city_labels = ["City", "Town/City"]
        for lbl in city_labels:
            try:
                await page.get_by_label(lbl).fill("San Francisco")
                break
            except Exception:
                continue

        # Select Region/State
        region_labels = ["State/Province", "Region", "State"]
        for rlbl in region_labels:
            try:
                elm = page.get_by_label(rlbl)
                try:
                    await elm.select_option(label="California")
                    break
                except Exception:
                    try:
                        await elm.select_option(value="CA")
                        break
                    except Exception:
                        continue
            except Exception:
                continue

        # Fill Postal Code
        postal_labels = ["Zip/Postal Code", "ZIP/Postal Code", "ZIP Code", "Postal Code", "Postcode"]
        for plbl in postal_labels:
            try:
                await page.get_by_label(plbl).fill("94102")
                break
            except Exception:
                continue

        # Ensure Country is United States if present
        try:
            await page.get_by_label("Country").select_option(label="United States")
        except Exception:
            try:
                await page.get_by_label("Country").select_option(value="US")
            except Exception:
                pass

    async def click_save_button():
        # Try likely save button names, prefer scoped selection to avoid ambiguity
        save_names = ["Save Address", "Save", "Save Changes"]
        for name in save_names:
            try:
                # try to find button within a form first
                try:
                    await page.get_by_role("form").get_by_role("button", name=name).click()
                except Exception:
                    await page.get_by_role("button", name=name).click()
                return True
            except Exception:
                continue
        # Final fallback: press Enter inside a known filled input to submit
        try:
            await page.get_by_label("City").press("Enter")
            return True
        except Exception:
            return False

    # 1) Edit Shipping Address (address_id=869)
    try:
        await page.goto("/index.php/admin/sales_order/address/address_id/869/")
        await page.wait_for_load_state("networkidle")
        await fill_address_fields()
        await click_save_button()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If anything fails, continue to attempt billing edit
        pass

    # 2) Edit Billing Address (address_id=868) -- make this the final navigation+save
    try:
        await page.goto("/index.php/admin/sales_order/address/address_id/868/")
        await page.wait_for_load_state("networkidle")
        await fill_address_fields()
        await click_save_button()
        await page.wait_for_load_state("networkidle")
    except Exception:
        pass

